import { LogicWrapper, MakeLogicType, afterMount, connect, kea, key, listeners, path, props } from 'kea'
import { loaders } from 'kea-loaders'
import posthog from 'posthog-js'

import { ApiError } from 'lib/api-error'
import { teamLogic } from 'scenes/teamLogic'

import * as api from '../generated/api'
import type { IncrementalEligibilityApi } from '../generated/api.schemas'

export interface SaveViewIncrementalLogicProps {
    query: string
    dialogKey: string
    setFormValue: (name: string, value: unknown) => void
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface saveViewIncrementalLogicValues {
    currentTeamId: number | null // teamLogic
    check: IncrementalEligibilityApi | null
    checkLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface saveViewIncrementalLogicActions {
    loadCheck: (_: void) => void
    loadCheckFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadCheckSuccess: (
        check: IncrementalEligibilityApi | null,
        payload?: void
    ) => {
        check: IncrementalEligibilityApi | null
        payload?: void
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface saveViewIncrementalLogicMeta {
    key: string
}

export type saveViewIncrementalLogicType = MakeLogicType<
    saveViewIncrementalLogicValues,
    saveViewIncrementalLogicActions,
    SaveViewIncrementalLogicProps,
    saveViewIncrementalLogicMeta
>

export const saveViewIncrementalLogic: LogicWrapper<saveViewIncrementalLogicType> = kea<saveViewIncrementalLogicType>([
    props({} as SaveViewIncrementalLogicProps),
    key(({ dialogKey, query }) => `${dialogKey}:${query}`),
    path((key) => ['products', 'data_warehouse', 'sql_editor', 'saveViewIncrementalLogic', key]),
    connect({ values: [teamLogic, ['currentTeamId']] }),
    loaders(({ props, values }) => ({
        check: [
            null as IncrementalEligibilityApi | null,
            {
                loadCheck: async (_: void, breakpoint) => {
                    let check: IncrementalEligibilityApi | null = null
                    try {
                        check = await api.warehouseSavedQueriesCheckIncrementalCreate(String(values.currentTeamId), {
                            query: props.query,
                        })
                    } catch (error) {
                        if (!(error instanceof ApiError && error.status && error.status >= 400 && error.status < 500)) {
                            posthog.captureException(error)
                        }
                    }
                    breakpoint()
                    return check
                },
            },
        ],
    })),
    listeners(({ props }) => ({
        loadCheck: () => {
            props.setFormValue('incrementalEnabled', false)
            props.setFormValue('incrementalKey', null)
            props.setFormValue('incrementalUniqueKey', [])
        },
        loadCheckSuccess: ({ check }) => {
            props.setFormValue('incrementalKey', check?.key_candidates[0] ?? null)
        },
    })),
    afterMount(({ actions }) => actions.loadCheck()),
])
